  return { before: clip(cut(a, i - ctx, a.length - j + ctx)), after: clip(cut(b, i - ctx, b.length - j + ctx)) };
}

// the changed articles between two versions of a law (law_full_text roots)
function diffLaw(oldRoot, newRoot) {
  const a = articlesOf(oldRoot), b = articlesOf(newRoot);
  const changed = [];
  for (const [k, v] of b) {
    const o = a.get(k);
    if (!o) changed.push({ key: k, label: v.label, caption: v.caption, type: 'added', before: '', after: v.text, diff_before: '', diff_after: v.text.length > 160 ? v.text.slice(0, 160) + '…' : v.text, suppl: v.suppl });
    else if (squash(o.text) !== squash(v.text)) { const s = snippet(o.text, v.text); changed.push({ key: k, label: v.label, caption: v.caption, type: 'modified', before: o.text, after: v.text, diff_before: s.before, diff_after: s.after, suppl: v.suppl }); }
  }
  for (const [k, v] of a) if (!b.has(k)) changed.push({ key: k, label: v.label, caption: v.caption, type: 'removed', before: v.text, after: '', diff_before: v.text.length > 160 ? v.text.slice(0, 160) + '…' : v.text, diff_after: '', suppl: v.suppl });
  changed.sort((x, y) => Number(x.suppl) - Number(y.suppl)); // main provisions first (stable: order of appearance)
  return { changed, total_old: a.size, total_new: b.size };
}

// ---- 2. the prompt input and the check of Claude's explanation ----------------------------------------
// what is sent to Claude: at most maxArticles changed articles, each cut to maxChars
function promptInput(diff, maxArticles, maxChars) {
  const cut = (s) => (s.length > maxChars ? s.slice(0, maxChars) + '…(cut)' : s);
  return diff.changed.slice(0, maxArticles).map((c) => ({ key: c.key, article: c.label, type: c.type, before: cut(c.before), after: cut(c.after) }));
}

// raw = Claude's text, diff = diffLaw result, cfg = { max_articles }
function checkExplanation(raw, diff, cfg) {
  let ai = null;
  try {
    const t = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const a = t.indexOf('{'), z = t.lastIndexOf('}');
    ai = JSON.parse(a >= 0 && z > a ? t.slice(a, z + 1) : t);
  } catch (e) { ai = null; }
  const lawProblems = [];
  if (!ai && diff.changed.length) lawProblems.push('the AI output could not be read as JSON');
  const byKey = new Map();
  for (const c of Array.isArray(ai?.changes) ? ai.changes : []) if (c && typeof c === 'object') byKey.set(String(c.key ?? ''), c);
  const known = new Set(diff.changed.map((c) => c.key));
  for (const k of byKey.keys()) if (!known.has(k)) lawProblems.push('the AI wrote about "' + k + '", which did not change');

  const max = Number(cfg.max_articles) || 20;
  const rows = diff.changed.map((c, i) => {
    const row = { key: c.key, article: c.label, caption: c.caption, type: c.type, diff_before: c.diff_before, diff_after: c.diff_after, explanation: '', quote_before: '', quote_after: '', status: '', problems: '' };
    if (i >= max) { row.status = 'Not explained'; row.problems = 'over the limit of ' + max + ' articles: only the code diff is shown'; return row; }
    const e = byKey.get(c.key);
    if (!e) { row.status = 'Needs review'; row.problems = 'the AI did not explain this article'; return row; }
    const problems = [];
    row.explanation = String(e.what_changed ?? '').trim();
    row.quote_before = String(e.quote_before ?? '').trim();
    row.quote_after = String(e.quote_after ?? '').trim();
    if (!row.explanation) problems.push('the explanation is empty');
    // a quote must be a stretch of the real text (before / after), and long enough to prove something
    const inText = (q, t) => squash(q).length >= 4 && squash(t).includes(squash(q));
    if (c.type !== 'removed') { if (!inText(row.quote_after, c.after)) problems.push('quote_after is not in the new text'); }
    if (c.type !== 'added') { if (!inText(row.quote_before, c.before)) problems.push('quote_before is not in the old text'); }
    // every number in the explanation must be in the old or the new text (kanji numerals count as numbers)
    const have = new Set([...numbersOf(c.before), ...numbersOf(c.after)]);
    for (const n of new Set(nfkc(row.explanation).match(/\d+/g) ?? [])) if (!have.has(n)) problems.push('the number ' + n + ' is not in the article');
    if (e.change_type && e.change_type !== c.type) problems.push('the AI called it "' + e.change_type + '", the code found "' + c.type + '"');
    row.status = problems.length ? 'Needs review' : 'OK';
    row.problems = problems.join('; ');
    return row;
  });
  return { rows, overview: String(ai?.overview ?? '').trim(), lawProblems };
}

// ---- 3. which laws have something new? ------------------------------------------------------------------
const STATUS_JA = { CurrentEnforced: '施行中', UnEnforced: '未施行（施行予定）', PreviousEnforced: '過去の版', Repeal: '廃止', Expire: '失効', Unknown: '不明' };
// revisions = law_revisions response (newest first), state = row of the Watch tab or null, demo = true: compare the two newest versions, change nothing
function decide(revisions, state, demo) {
  const list = revisions?.revisions ?? [];
  const info = revisions?.law_info ?? {};
  const newest = list[0];
  if (!newest) return { kind: 'none' };
  const base = { law_id: info.law_id, law_num: info.law_num, to_rev: newest.law_revision_id, to_title: newest.law_title, enforcement_date: newest.amendment_enforcement_date ?? '', status: newest.current_revision_status ?? '',
    status_ja: STATUS_JA[newest.current_revision_status] ?? newest.current_revision_status ?? '', amend_title: newest.amendment_law_title ?? '', amend_num: newest.amendment_law_num ?? '', promulgated: newest.amendment_promulgate_date ?? '' };
  if (demo) return list.length > 1 ? { kind: 'compare', ...base, from_rev: list[1].law_revision_id, demo: true } : { kind: 'none' };
  if (!state || !state.last_revision_id) return { kind: 'baseline', ...base };
  if (state.last_revision_id === newest.law_revision_id) return { kind: 'none' };
  // a revision we have not seen: compare the last one we saw with the newest (if the old one is gone from the list, the second newest)
  const known = list.some((r) => r.law_revision_id === state.last_revision_id);
  return { kind: 'compare', ...base, from_rev: known ? state.last_revision_id : (list[1]?.law_revision_id ?? state.last_revision_id) };
}

const cfg = $('Config').first().json;
return $input.all().map((it, i) => {
  const d = $('Diff articles').all()[i].json;
  const raw = it.json.content?.[0]?.text ?? it.json.text;
  const r = checkExplanation(d.changed.length ? raw : '{"overview":"","changes":[]}', { changed: d.changed }, cfg);
  const flagged = r.rows.filter((x) => x.status === 'Needs review').length;
  const counts = { added: 0, removed: 0, modified: 0 };
  d.changed.forEach((c) => counts[c.type]++);
  const mark = (x) => (x.status === 'OK' ? '' : x.status === 'Not explained' ? ' (説明なし)' : ' :warning:');
  const lines = r.rows.slice(0, 15).map((x) => '• ' + x.article + (x.caption ? ' ' + x.caption : '') + ' [' + ({ added: '追加', removed: '削除', modified: '変更' })[x.type] + ']' + mark(x) +
    (x.explanation ? '\n   ' + x.explanation : '') + (x.diff_before || x.diff_after ? '\n   差分: 「' + x.diff_before + '」→「' + x.diff_after + '」' : ''));
  const head = ':scroll: *' + d.to_title + '* の改正を検出' + (d.demo ? '（デモ：直近の改正）' : '') + '\n施行日: ' + d.enforcement_date + '（' + d.status_ja + '）　改正法令: ' + d.amend_title + (d.amend_num ? '（' + d.amend_num + '）' : '');
  const body = d.changed.length ? '条文の差分（コードが検出）: 追加 ' + counts.added + ' / 削除 ' + counts.removed + ' / 変更 ' + counts.modified + '\n' + (r.overview ? r.overview + '\n' : '') + lines.join('\n') +
    (r.rows.length > 15 ? '\n• ...ほか ' + (r.rows.length - 15) + ' 条（Changes タブを参照）' : '') : '条文の本文に差はありませんでした（改正履歴の更新のみ）。';
  const warn = (flagged ? '\n:warning: ' + flagged + ' 件は AI の説明が確認を通りませんでした。差分と条文を直接見てください。' : '') + (r.lawProblems.length ? '\n:warning: ' + r.lawProblems.join('; ') : '');
  const foot = '\n_法的な助言ではありません。条文: https://laws.e-gov.go.jp/law/' + d.law_id + ' ／ ' + d.from_rev + ' → ' + d.to_rev + '_';
  const detected = $now.toISO();
  const change_rows = r.rows.map((x) => ({ change_id: d.to_rev + '|' + x.key, detected_at: detected, law_id: d.law_id, law_title: d.to_title, from_revision: d.from_rev, to_revision: d.to_rev,
    enforcement_date: d.enforcement_date, enforcement_status: d.status, article: x.article, caption: x.caption, change_type: x.type, diff_before: x.diff_before, diff_after: x.diff_after,
    explanation: x.explanation, quote_before: x.quote_before, quote_after: x.quote_after, status: x.status, problems: x.problems }));
  if (!change_rows.length) change_rows.push({ change_id: d.to_rev + '|none', detected_at: detected, law_id: d.law_id, law_title: d.to_title, from_revision: d.from_rev, to_revision: d.to_rev, enforcement_date: d.enforcement_date,
    enforcement_status: d.status, article: '', caption: '', change_type: 'no text change', diff_before: '', diff_after: '', explanation: '', quote_before: '', quote_after: '', status: 'OK', problems: d.read_problem ?? '' });
  return { json: { ...d, changed: undefined, prompt_articles: undefined, slack_text: head + '\n' + body + warn + foot, change_rows, flagged } };
});

// first time this law is seen: remember the newest version, say so, compare nothing
// (a law that could not be read is reported too, so a wrong ID does not go unnoticed)
return $input.all().map((it) => it.json).map((d) => (d.kind === 'error'
  ? { json: { ...d, slack_text: ':x: 法令 ' + d.law_id + ' を読めませんでした: ' + d.problem } }
  : { json: { ...d, slack_text: ':eyes: *' + d.to_title + '* の見張りを始めました。\n最新の版: ' + d.to_rev + '（施行日 ' + d.enforcement_date + '、' + d.status_ja + '）\n次に改正があれば、変わった条文をお知らせします。' } }));

// the Watch tab remembers the newest version of each law, so that the next run compares from there (the demo changes nothing)
const cfg = $('Config').first().json;
if (cfg.demo === true || cfg.demo === 'true') return [];
const rows = [];
const take = (name) => { try { return $(name).all().map((i) => i.json); } catch (e) { return []; } };
for (const d of [...take('Baseline note'), ...take('Check explanation')].filter((x) => x.to_rev)) rows.push({ law_id: d.law_id, law_title: d.to_title, last_revision_id: d.to_rev, last_enforcement_date: d.enforcement_date, last_status: d.status, last_checked: $now.toISO() });
return rows.map((r) => ({ json: r }));
